function attach(h,{id='root:note.md',sha='sha-a',text='磁盘正文',writable=true}={}){h.ui.state.file={id,sha,text,writable,title:id,path:id,links:[],backlinks:[]};h.ui.state.draftBase=sha;h.get('editor').value=text;return h.ui.state.file;}
test('document draft is scoped, validates base hash and contains only recovery fields',()=>{const storage=new MemoryStorage(),store=createWorkspaceDraftStore(storage,'a'),other=createWorkspaceDraftStore(storage,'b');assert.equal(store.saveDocument('doc','sha','草稿'),true);assert.equal(store.document('doc').text,'草稿');assert.equal(other.document('doc'),null);assert.equal(store.saveDocument('doc',{token:'must-not-store'},'x'),false);assert.deepEqual(Object.keys(JSON.parse([...storage.map.values()][0])).sort(),['base_sha','id','text','updated_at']);});
test('corrupt stored JSON and unexpected objects do not break loading',()=>{const storage=new MemoryStorage(),store=createWorkspaceDraftStore(storage,'x');storage.setItem('upward.workspace.recovery.v1:x:document:a','{');assert.equal(store.document('a'),null);storage.setItem('upward.workspace.recovery.v1:x:document:a','{"id":"a","text":1}');assert.equal(store.document('a'),null);});
test('quota failure is returned rather than silently claiming protection',()=>{const store=createWorkspaceDraftStore({setItem(){throw Error('quota');},getItem(){return null;}},'x');assert.equal(store.saveChat('a','draft'),false);assert.equal(store.saveDocument('a','sha','draft'),false);});
test('draft recovery distinguishes saved contents, same base and external conflicts',()=>{const file={id:'a',sha:'new',text:'disk'};assert.equal(workspaceDraftRecovery({id:'a',base_sha:'old',text:'disk'},file).kind,'saved');assert.equal(workspaceDraftRecovery({id:'a',base_sha:'new',text:'draft'},file).kind,'restored');assert.equal(workspaceDraftRecovery({id:'a',base_sha:'old',text:'draft'},file).kind,'conflict');});
test('unsent inputs are independent for new chat and each existing session',()=>{const store=createWorkspaceDraftStore(new MemoryStorage(),'x');store.saveChat('','new');store.saveChat('a','A');store.saveChat('b','B');store.saveChat('a','');assert.equal(store.chat(''),'new');assert.equal(store.chat('a'),'');assert.equal(store.chat('b'),'B');});
test('history merge retains earlier messages, deduplicates and updates newer values',()=>{const current=[{id:'b',text:'old'},{id:'c',text:'C'}];const merged=mergeWorkspaceMessages(current,[{id:'a',text:'A'},{id:'b',text:'updated'}],true);assert.equal(merged.map(x=>x.id).join(','),'a,b,c');assert.equal(merged[1].text,'updated');assert.equal(mergeWorkspaceMessages(merged,[{id:'d',text:'D'}]).map(x=>x.id).join(','),'a,b,c,d');});
test('idle and error polling is bounded and slower than active streaming',()=>{assert.equal(workspacePollDelay(true,0),1200);assert.equal(workspacePollDelay(false,0),10000);assert.equal(workspacePollDelay(false,1),3000);assert.equal(workspacePollDelay(true,10),30000);});
test('restored external-conflict draft stays editable in memory but cannot overwrite disk',async()=>{const h=harness();h.ui.drafts().saveDocument('root:note.md','old','恢复草稿');const opening=h.ui.openFile('root:note.md');await settle();h.requests[0].respond({id:'root:note.md',sha:'new',text:'外部内容',writable:true,path:'note.md'});await opening;assert.equal(h.get('editor').value,'恢复草稿');assert.equal(h.ui.state.draftConflict,true);assert.equal(h.get('save-note').disabled,true);await h.ui.saveNote();assert.equal(h.requests.length,1);});
