test('AI receipt undo preserves newly typed draft and detects disk conflict',async()=>{const h=harness();attach(h);const button=element('undo');button.dataset={undo:'u1',sha:'sha-a'};const pending=h.ui.undoReceipt(button);await settle();h.get('editor').value='new during AI undo';h.get('editor').fire('input');h.ui.persistDocumentDraft();h.requests[0].respond({id:'root:note.md',sha:'undo-sha'});await settle();h.requests[1].respond({id:'root:note.md',sha:'undo-sha'});await pending;assert.equal(h.get('editor').value,'new during AI undo');assert.equal(h.ui.state.draftConflict,true);assert.equal(h.ui.drafts().document('root:note.md').text,'new during AI undo');});
test('chat storage failures block session navigation and retain unsent text',async()=>{for(const storage of [null,{getItem(){return null;},setItem(){throw Error('quota');},removeItem(){throw Error('quota');}}])for(const target of ['','b']){const h=harness();h.ui.useStorage(storage);h.ui.state.session='a';h.get('message').value='未发送问题';h.get('session-select').value=target;await h.ui.selectSession(target);assert.equal(h.ui.state.session,'a');assert.equal(h.get('session-select').value,'a');assert.equal(h.get('message').value,'未发送问题');assert.equal(h.get('chat-draft-state').hidden,false);assert.equal(h.requests.length,0);}});

test('connection labels use wiki aliases and Markdown text without changing link targets',()=>{const h=harness(),target='项目/今天做视频--977babcdef123456.md',file_id='upward:encoded-original';const wiki=h.ui.connectionLink({target,file_id,title:'今天做视频--977babcdef123456'},'[[项目/今天做视频--977babcdef123456.md|今天做视频]]');assert.equal(wiki.label,'今天做视频');assert.equal(wiki.id,file_id);assert.equal(wiki.target,target);const md=h.ui.connectionLink({target,file_id,title:target},'[我的视频计划](项目/今天做视频--977babcdef123456.md)');assert.equal(md.label,'我的视频计划');assert.equal(md.target,target);const fallback=h.ui.connectionLink({target,file_id,title:target},'');assert.equal(fallback.label,'今天做视频');assert.equal(fallback.id,file_id);});
test('connection buttons keep backend document IDs, ignore code examples, and use readable backlinks',async()=>{const h=harness();attach(h,{text:'```md\n[[a.md|伪别名]]\n```\n[[a.md|真实别名]]'});h.ui.state.file.links=[{target:'a.md',file_id:'root:real-a.md',title:'a'}];h.ui.state.file.backlinks=[{file_id:'root:real-b.md',title:'来源--977babcdef123456'}];h.ui.renderConnections();const buttons=h.get('connections').children.filter(x=>x.listeners.click);assert.equal(buttons[0].textContent,'真实别名');assert.equal(buttons[1].textContent,'来源');buttons[0].fire('click');await settle();assert.match(h.requests[0].url,/id=root%3Areal-a.md/);});

test('growth-view send transmits purpose and scope but never attaches a hidden previous document',async()=>{const h=harness();attach(h);h.ui.state.workspaceView='review';h.ui.state.growthContext={purpose:'review',scope:'personal',days:30,advisor_names:['naval-perspective']};h.ui.state.selectedModel='verified-model';h.get('message').value='阶段复盘';const pending=h.ui.sendMessage({preventDefault(){}});const payload=JSON.parse(h.requests[0].options.body);assert.equal(payload.purpose,'review');assert.equal(payload.days,30);assert.equal(payload.current_file_id,undefined);assert.equal(payload.allow_write,false);assert.deepEqual(payload.advisor_names,['naval-perspective']);h.requests[0].respond({error:'test intercepted'},400);await pending;assert.equal(h.get('message').value,'阶段复盘');});
test('document scope rejects missing visible attachment before model submission',async()=>{const h=harness();attach(h);h.ui.state.workspaceView='daily';h.ui.state.growthContext={purpose:'daily',scope:'document',days:7,advisor_names:[]};h.ui.state.selectedModel='verified';h.get('message').value='test';await h.ui.sendMessage({preventDefault(){}});assert.equal(h.requests.length,0);assert.match(h.get('chat-notice').textContent,/先打开并附上/);});


test('attachments enforce size/count/type before upload and retain explicit failures',async()=>{const h=harness();await h.ui.addAttachments([{name:'too.pdf',size:20971521},{name:'bad.exe',size:2}]);assert.equal(h.requests.length,0);assert.match(h.get('chat-notice').textContent,/暂不支持/);const upload=h.ui.addAttachments([{name:'ok.md',size:5}]);await settle();assert.equal(h.ui.currentAttachments()[0].status,'uploading');assert.equal(h.get('send').disabled,true);assert.equal(h.requests[0].url,'/api/workspace/attachments');h.requests[0].respond({error:'解析失败'},400);await upload;assert.equal(h.ui.currentAttachments()[0].status,'failed');assert.match(h.get('attachment-list').innerHTML,/解析失败/);h.ui.removeAttachment(h.ui.currentAttachments()[0].key);assert.equal(h.ui.currentAttachments().length,0);for(let i=0;i<8;i++)h.ui.currentAttachments().push({id:String(i),name:'n',status:'ready'});await h.ui.addAttachments([{name:'ninth.md',size:1}]);assert.equal(h.requests.length,1);assert.match(h.get('chat-notice').textContent,/最多添加 8/);});
test('upload completion stays with original session, stores no path or binary, and removal cannot resurrect it',async()=>{const h=harness();h.ui.state.session='A';const upload=h.ui.addAttachments([{name:'n.md',size:5}]);await settle();const key=h.ui.currentAttachments()[0].key;h.ui.removeAttachment(key);await h.ui.selectSession('');h.requests[0].respond({attachment:{id:'att-a',name:'n.md',bytes:5,status:'ready',path:'/private/secret',data_base64:'secret'}});await settle();assert.equal(h.requests[1].url,'/api/workspace/attachments/remove');h.requests[1].respond({deleted:true});await upload;assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.ui.drafts().attachments('A').length,0);assert.doesNotMatch([...h.storage.map.values()].join(''),/private|data_base64/);});
test('ready attachments recover separately and pure attachment send uses IDs only',async()=>{const h=harness();h.ui.drafts().saveAttachments('A',[{id:'att-a',key:'a',name:'photo.png',status:'ready',bytes:5}]);const selecting=h.ui.selectSession('A',true);h.requests[0].respond({messages:[],jobs:[]});await selecting;assert.equal(h.ui.currentAttachments()[0].id,'att-a');h.ui.state.selectedModel='verified';h.ui.updateChatControls();assert.equal(h.get('send').disabled,false);const sending=h.ui.sendMessage({preventDefault(){}});const body=JSON.parse(h.requests[1].options.body);assert.deepEqual(body.attachment_ids,['att-a']);assert.equal(body.message,'');h.requests[1].respond({error:'intercept'},400);await sending;assert.equal(h.ui.currentAttachments()[0].id,'att-a');});
test('native speech only starts on click, ignores stale result and inserts editable text without send',async()=>{const h=harness(),calls=[];h.window.upwardNativeSpeech=true;h.window.webkit={messageHandlers:{upwardSpeech:{postMessage:v=>calls.push(v)}}};assert.equal(calls.length,0);h.get('message').value='已写内容';h.ui.toggleSpeech();assert.equal(calls[0].action,'start');const ticket=h.ui.state.speech;h.window.fire('upward-speech',{detail:{state:'result',request_id:'old',text:'错误文字'}});assert.equal(h.get('message').value,'已写内容');h.window.fire('upward-speech',{detail:{state:'result',request_id:ticket.id,text:'新的口述',final:true}});assert.equal(h.get('message').value,'已写内容\n新的口述');assert.equal(h.requests.length,0);assert.equal(h.ui.state.speech,null);h.ui.toggleSpeech();h.ui.cancelSpeech();h.window.fire('upward-speech',{detail:{state:'result',request_id:ticket.id,text:'迟到'}});assert.doesNotMatch(h.get('message').value,/迟到/);assert.equal(calls.at(-1).action,'cancel');});
test('unsupported speech gives real fallback and browser recognizer ignores results after cancellation',()=>{const h=harness();h.ui.toggleSpeech();assert.match(h.get('speech-status').textContent,/系统设置 → 键盘 → 听写/);let recognizer;h.window.SpeechRecognition=class{constructor(){recognizer=this;}start(){}abort(){}stop(){}};h.ui.toggleSpeech();h.ui.cancelSpeech();recognizer.onresult({resultIndex:0,results:[Object.assign([{transcript:'late'}],{isFinal:true})]});assert.equal(h.get('message').value,'');assert.equal(h.requests.length,0);});
