test('historical rounds retain independent disclosure state across renders',()=>{const h=harness(),el=h.get('conversation');h.ui.state.jobs=['one','two'].map(id=>({id,status:'failed',updated_at:'2026-10-12T12:00:00Z'}));h.ui.state.messages=[{id:'reply',job_id:'next',role:'assistant',status:'completed',created_at:'2026-10-12T13:00:00Z',text:'done'}];h.ui.renderConversation();assert.match(el.innerHTML,/data-message-id="history-one"/);assert.match(el.innerHTML,/data-message-id="history-two"/);const detail=(id,open)=>({open,closest:()=>({dataset:{messageId:'history-'+id}}),querySelector:()=>({textContent:'先前一轮未完成 · 后续已有回复'})});const before=[detail('one',true),detail('two',false)],after=[detail('one',false),detail('two',false)];let calls=0;el.querySelectorAll=selector=>selector==='details'?(calls++===0?before:after):[];h.ui.state.chatSignature='';h.ui.renderConversation();assert.equal(after[0].open,true);assert.equal(after[1].open,false);});

// Keep disclosure content out when asserting what a user sees without expanding.
function evidenceAtRest(html){let depth=0;return html.split(/(<\/?details\b[^>]*>)/i).filter(part=>{if(/^<details\b/i.test(part)){depth++;return false;}if(/^<\/details/i.test(part)){depth--;return false;}return depth===0;}).join('');}
test('selected advisors and three read titles stay visible with reason and extra sources folded',()=>{const h=harness(),data={advisor_selection:[{title:'纳瓦尔',name:'naval',status:'selected',reason:'因为本轮讨论个人事业'}],references:Array.from({length:5},(_,i)=>({id:'root:doc'+i,title:'材料'+i,line:i+1}))},html=h.ui.compactEvidenceHTML(data),visible=evidenceAtRest(html);assert.match(visible,/本轮顾问 · 纳瓦尔/);assert.match(visible,/本轮读取 · 5 份/);for(let i=0;i<3;i++){assert.match(visible,new RegExp('材料'+i));assert.match(visible,new RegExp('data-open="root:doc'+i+'"'));}assert.doesNotMatch(visible,/材料3|材料4|因为本轮/);assert.match(html,/更多已读资料 · 2/);assert.match(html,/查看选用理由/);assert.match(html,/因为本轮讨论个人事业/);assert.doesNotMatch(html,/<details[^>]* open/);});
test('live and completed evidence distinguish absence, reads and selection',()=>{const h=harness();assert.match(evidenceAtRest(h.ui.compactEvidenceHTML({},{live:true})),/尚未选用/);assert.match(evidenceAtRest(h.ui.compactEvidenceHTML({},{live:true})),/尚未读取/);const readOnly=h.ui.compactEvidenceHTML({advisor_reads:[{name:'naval',title:'纳瓦尔方法',skill_id:'advisor:skill',sha:'s'}],references:[{id:'advisor:skill',title:'纳瓦尔方法',sha:'s',line:1},{id:'advisor:skill',title:'纳瓦尔方法',sha:'s',line:100}]});assert.match(evidenceAtRest(readOnly),/本轮无顾问选用回执/);assert.match(evidenceAtRest(readOnly),/本轮读取 · 1 份/);assert.doesNotMatch(evidenceAtRest(readOnly),/本轮顾问 ·/);const none=h.ui.compactEvidenceHTML({advisor_selection:[{title:'候选顾问',status:'requested'}]});assert.match(evidenceAtRest(none),/无本轮读取回执/);assert.doesNotMatch(none,/本轮顾问 · 候选顾问/);});
test('search receipts never become read receipts and zero hits remain explicit',()=>{const h=harness(),html=h.ui.compactEvidenceHTML({knowledge_searches:[{query:'做视频',count:0,root_id:'upward',at:'2026-10-13'},{query:'未知结果数',count:null}]},{live:true});assert.match(evidenceAtRest(html),/尚未读取/);assert.match(html,/本轮搜索 · 2 次（搜索不等于读取）/);assert.match(html,/做视频 · 0 条结果/);assert.match(html,/未知结果数 · 结果数未记录/);assert.doesNotMatch(html,/本轮读取 ·/);});
test('previous evidence and provided snapshots never masquerade as current selection or reads',()=>{const h=harness(),html=h.ui.compactEvidenceHTML({reply_context:{previous_evidence:{advisors:[{title:'历史纳瓦尔'}],references:[{id:'root:old',title:'旧资料'}],source_job_id:'previous-job',recorded_at:'2026-10-12'},provided_context:[{title:'成长概况 · 近7天',kind:'growth_snapshot',status:'provided'}]}}),visible=evidenceAtRest(html);assert.match(visible,/本轮无顾问选用回执/);assert.match(visible,/无本轮读取回执/);assert.doesNotMatch(visible,/历史纳瓦尔|旧资料|成长概况/);assert.match(html,/历史参考记录（不代表本轮使用）/);assert.match(html,/来源轮次：previous-job/);assert.match(html,/自动提供的概况，不等同于本轮原文读取/);assert.doesNotMatch(html,/沿用上文|本回答引用/);});
test('empty native list cannot mask knowledge tools, combined lists deduplicate identical receipts',()=>{const h=harness(),tool={name:'knowledge_read',status:'completed',call_id:'kb-read'},native={name:'commandExecution',status:'completed',item_id:'cmd',detail:{command:'pwd'}};assert.match(h.ui.nativeEventsHTML({native_tools:[],tool_events:[tool]}),/读取资料/);const html=h.ui.nativeEventsHTML({native_tools:[native],tool_events:[tool,native,{type:'reasoning',text:'RAW_PRIVATE_REASONING'},{type:'tool',kind:'analysis',text:'HIDDEN_ANALYSIS'}]});assert.match(html,/本轮执行记录 · 2/);assert.match(html,/读取资料/);assert.match(html,/执行命令/);assert.doesNotMatch(html,/RAW_PRIVATE_REASONING|HIDDEN_ANALYSIS/);});
test('new evidence escapes all names and queries while live rendering explicitly passes its phase',()=>{const h=harness(),html=h.ui.compactEvidenceHTML({advisor_selection:[{name:'<img>',reason:'<script>bad</script>'}],references:[{id:'root:"',title:'<svg>'}],knowledge_searches:[{query:'<iframe>',count:1}],previous_evidence:{advisors:[{title:'<input>'}]}});assert.doesNotMatch(html,/<img>|<script>|<svg>|<iframe>|<input>/);assert.match(html,/&lt;img&gt;/);assert.match(html,/data-open="root:&quot;"/);h.ui.state.jobs=[{id:'live',status:'running',advisor_selection:[],references:[]}];h.ui.renderConversation();assert.match(h.get('conversation').innerHTML,/尚未选用/);assert.match(h.get('conversation').innerHTML,/尚未读取/);});

test('startup failure keeps prepared snapshots unprovided until accepted turn receipt arrives',()=>{const h=harness(),context={provided_context:[{title:'成长概况 · 近7天',kind:'growth_snapshot',status:'prepared'}]},failed=h.ui.compactEvidenceHTML({status:'failed',error:'turn start failed',reply_context:context});assert.match(failed,/准备附带概况 · 1 项/);assert.match(failed,/尚未确认交给模型/);assert.doesNotMatch(failed,/已提供概况/);context.provided_context[0].status='provided';const accepted=h.ui.compactEvidenceHTML({reply_context:context});assert.match(accepted,/已提供概况 · 1 项/);assert.doesNotMatch(accepted,/准备附带概况/);const unknown=h.ui.compactEvidenceHTML({provided_context:[{title:'旧记录无交付状态'}]});assert.match(unknown,/概况交付状态待核实/);assert.doesNotMatch(unknown,/已提供概况/);});

test('long visible evidence titles remain bounded and clickable with full tooltips',()=>{const h=harness(),title='这是必须完整保留且不能撑高窄聊天窗口的标题'.repeat(20),html=h.ui.compactEvidenceHTML({advisor_selection:[{title,reason:'完整选用理由'}],references:[0,1,2].map(i=>({id:'root:long'+i,title:title+i}))},{live:true}),visible=evidenceAtRest(html),css=fs.readFileSync(path.join(__dirname,'../web/workspace.css'),'utf8');for(let i=0;i<3;i++){assert.ok(visible.includes('title="'+title+i+'"'));assert.ok(visible.includes('data-open="root:long'+i+'"'));}assert.doesNotMatch(html,/<details[^>]* open/);assert.match(css,/\.turn-evidence \.evidence-advisors\{[^}]*-webkit-line-clamp:2;[^}]*max-height:30px;[^}]*overflow:hidden/);assert.match(css,/\.turn-evidence \.evidence-source\{[^}]*white-space:nowrap;[^}]*overflow:hidden;[^}]*text-overflow:ellipsis;[^}]*overflow-wrap:normal/);assert.match(css,/\.turn-evidence>details\[open\]\{grid-column:1\/-1\}/);assert.match(css,/\.turn-evidence>details>summary\{[^}]*white-space:nowrap;[^}]*overflow:hidden;[^}]*text-overflow:ellipsis/);});


test('C20 shared selection previews without auto send, invalidation keeps question and no vault citation path',async()=>{
 const h=harness(),id='SHR-'+ '1'.repeat(32);h.ui.state.selectedModel='sample';h.ui.state.growthContext.scope='advisors';h.get('message').value='请比较公开样本';h.ui.shared.scope={instance_id:'sample',generation:1,scope_fingerprint:'a'.repeat(64)};h.ui.shared.items=[{share_id:id,version:1,state:'active'}];h.ui.shared.selected.set(id,1);
 const pending=h.ui.sendMessage({preventDefault(){}});assert.match(h.requests[0].url,/shared\/preview/);assert.equal(h.requests.length,1);
 h.requests[0].respond({preview_id:'p',preview_sha256:'s',expires_at:Date.now()/1000+300,question:'请比较公开样本',model:'sample',policy:{scope:'advisors',execution_mode:'knowledge'},items:[{share_id:id,title:'安全标题',source_kind:'text',line_reference:'提取正文',locator:{line_start:7,line_count:1},text:'公开样本正文'}]});await pending;
 assert.equal(h.requests.length,1);assert.equal(h.get('confirm-shared-send').disabled,true);assert.ok(h.ui.shared.preview);
 h.get('message').value='问题已改变';h.get('message').fire('input');assert.equal(h.ui.shared.preview,null);assert.equal(h.get('shared-send-preview').children.length,0);h.get('shared-send-ack').checked=true;await h.ui.sendMessage({preventDefault(){}},true);assert.equal(h.requests.length,1);assert.equal(h.get('message').value,'问题已改变');assert.equal(h.ui.shared.selected.size,1);
 const retry=h.ui.previewSharedSend();h.requests[1].respond({error:{message:'来源暂不可核验',retryable:true}},503);await retry;assert.equal(h.ui.shared.selected.size,1);assert.equal(h.get('message').value,'问题已改变');assert.match(h.get('shared-send-status').textContent,/问题与选择保留/);
 h.ui.shared.preview={preview_id:'old-confirmation'};h.ui.renderSharedChoices();const view=h.get('shared-choices').children.find(v=>v.textContent==='查看片段');const peek=view.listeners.click[0].fn();assert.equal(h.ui.shared.preview,null);h.requests.at(-1).respond({items:[{share_id:id,title:'安全标题',line_reference:'提取正文',text:'只读查看文字'}]});await peek;h.get('shared-send-ack').checked=true;h.get('shared-send-ack').fire('change');assert.equal(h.get('confirm-shared-send').disabled,true);
 const sourceNotice='网页完整性尚未核验；部分提取，OCR 待人工核对 <原页>';const html=h.ui.compactEvidenceHTML({references:[{kind:'shared',id,title:'安全标题',line_reference:sourceNotice,version:1,shared_scope:h.ui.shared.scope}]});assert.match(html,/data-shared-open/);assert.equal((html.match(/class="shared-source-note"/g)||[]).length,2);assert.equal((html.match(/title="网页完整性尚未核验；部分提取，OCR 待人工核对 &lt;原页&gt;"/g)||[]).length,2);assert.doesNotMatch(html,/<原页>/);assert.doesNotMatch(html,/data-open=/);assert.doesNotMatch(h.ui.markdown('[片段](vault:'+id+')'),/data-open=/);
});

test('ready attachment removal waits for disk receipt and failure retains recoverable draft',async()=>{
 const h=harness();h.ui.state.session='A';h.ui.currentAttachments().push({id:'a',key:'a',draft_id:'draft-a',name:'a.txt',status:'ready'});h.ui.persistChatDraft();
 let removal=h.ui.removeAttachment('a');assert.equal(h.requests[0].url,'/api/workspace/attachments/remove');assert.equal(h.ui.currentAttachments().length,1);assert.equal(h.ui.currentAttachments()[0].removing,true);
 h.requests[0].respond({error:'locked'},409);await removal;assert.equal(h.ui.currentAttachments().length,1);assert.equal(h.ui.drafts().attachments('A')[0].draft_id,'draft-a');assert.match(h.get('chat-notice').textContent,/移除失败/);
 removal=h.ui.removeAttachment('a');h.requests[1].respond({deleted:true});await removal;assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.ui.drafts().attachments('A').length,0);
});
test('an attachment referenced by another saved draft is kept without a delete request',async()=>{
 const h=harness();const a={id:'a',key:'a',draft_id:'draft-a',name:'a.txt',status:'ready'};h.ui.state.session='A';h.ui.currentAttachments().push(a);h.ui.drafts().saveAttachments('B',[a]);
 await h.ui.removeAttachment('a');assert.equal(h.requests.length,0);assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.ui.drafts().attachments('B')[0].id,'a');
});
test('cross-tab shared-draft removal updates visible attachments without losing typed text',()=>{
 const h=harness();h.ui.state.session='A';h.ui.currentAttachments().push({id:'a',key:'a',draft_id:'draft-a',name:'a.txt',status:'ready'});h.get('message').value='本标签仍在输入';h.ui.persistChatDraft();
 const key=[...h.storage.map.keys()].find(k=>k.includes(':attachments:'));h.ui.drafts().saveAttachments('A',[]);h.window.fire('storage',{key});
 assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.get('message').value,'本标签仍在输入');h.ui.persistChatDraft();assert.equal(h.ui.drafts().attachments('A').length,0);
});
test('late upload cleanup failure restores a removable attachment rather than an orphan',async()=>{
 const h=harness();const upload=h.ui.addAttachments([{name:'a.txt',size:5}]);await settle();await h.ui.removeAttachment(h.ui.currentAttachments()[0].key);h.requests[0].respond({attachment:{id:'late',name:'a.txt',bytes:5,status:'ready'}});await settle();
 h.requests[1].respond({error:'offline'},503);await upload;assert.equal(h.ui.currentAttachments()[0].id,'late');assert.equal(h.ui.currentAttachments()[0].status,'ready');assert.match(h.get('chat-notice').textContent,/清理失败/);
});

test('slow model startup cannot override early navigation or newly typed input',async()=>{
 const h=harness();
 h.storage.setItem('upward.workspace.recovery.v1:boot:chat:new',JSON.stringify({text:'已恢复草稿'}));
 const starting=h.ui.start();h.requests[0].respond({token:'synthetic',data_id:'boot'});await settle();
 assert.equal(h.get('message').disabled,false);assert.equal(h.get('message').value,'已恢复草稿');
 h.get('growth-navigation').fire('click',{target:{closest(){return {dataset:{growthView:'learn'}};}}});h.get('message').value='启动等待期间继续输入';
 for(const request of h.requests.slice(1))if(request.url!=='/api/models')request.respond(request.url==='/api/vault/roots'?{roots:[]}:request.url.startsWith('/api/workspace/sessions')?{sessions:[]}:{execution_modes:[]});
 await settle();assert.equal(h.ui.state.workspaceView,'learn');
 h.requests.find(r=>r.url==='/api/models').respond({models:[]});await starting;
 assert.equal(h.ui.state.workspaceView,'learn');assert.equal(h.get('message').value,'启动等待期间继续输入');
});
test('startup keeps today default and restores a saved document draft without navigating during load',async()=>{
 const h=harness();
 h.storage.setItem('upward.workspace.boot.lastFile','notes:a.md');
 h.storage.setItem('upward.workspace.recovery.v1:boot:document:notes%3Aa.md',JSON.stringify({id:'notes:a.md',base_sha:'sha',text:'草稿原字'}));
 const starting=h.ui.start();h.requests[0].respond({token:'synthetic',data_id:'boot'});await settle();assert.equal(h.ui.state.workspaceView,'daily');
 for(const request of h.requests.slice(1))request.respond(request.url==='/api/vault/roots'?{roots:[]}:request.url==='/api/models'?{models:[]}:request.url.startsWith('/api/workspace/sessions')?{sessions:[]}:{execution_modes:[]});
 await settle();const reading=h.requests.find(r=>r.url.startsWith('/api/vault/read?'));assert.ok(reading);reading.respond({id:'notes:a.md',sha:'sha',text:'磁盘正文',writable:true});await starting;
 assert.equal(h.ui.state.workspaceView,'knowledge');assert.equal(h.ui.state.dirty,true);assert.equal(h.get('editor').value,'草稿原字');
});

test('lost deletion receipt keeps the chip retryable and a confirmed retry clears it',async()=>{
 const h=harness();h.ui.state.session='A';h.ui.currentAttachments().push({key:'a',id:'a',name:'a.txt',status:'ready',draft_id:'draft-a'});h.ui.persistChatDraft();
 let removal=h.ui.removeAttachment('a');h.requests[0].reject(new TypeError('删除后回执断开'));await removal;
 assert.equal(h.ui.currentAttachments()[0].status,'ready');assert.equal(h.ui.currentAttachments()[0].removing,false);
 removal=h.ui.removeAttachment('a');assert.equal(h.requests[1].url,'/api/workspace/attachments/remove');h.requests[1].respond({deleted:true});await removal;
 assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.ui.drafts().attachments('A').length,0);
});

test('workspace panes keep explicit tracks when navigation leaves the grid and narrow hidden states stay coherent',()=>{const css=fs.readFileSync(path.join(__dirname,'../web/workspace.css'),'utf8');for(const [selector,column] of [['.library',1],['#left-divider',2],['.document-panel',3],['#right-divider',4],['.chat-panel',5]])assert.ok(css.includes('.workspace>'+selector+'{grid-column:'+column+';grid-row:1}'),selector);assert.ok(css.includes('body.nav-hidden #left-divider,body.chat-hidden #right-divider{display:none}'));assert.ok(css.includes('@media(max-width:900px){.workspace,body.nav-hidden .workspace{grid-template-columns:0 0 minmax(270px,1fr) 1px min(var(--chat-width),calc(100vw - 271px))}'));assert.match(css,/\.library,body\.nav-hidden \.library\{[^}]*position:fixed;[^}]*visibility:visible;[^}]*display:none/);assert.ok(css.includes('body.nav-open .library{display:flex}'));assert.ok(css.includes('body.chat-hidden .workspace,body.chat-hidden.nav-hidden .workspace{grid-template-columns:0 0 minmax(270px,1fr) 0 0}'));assert.ok(css.includes('@media(max-width:640px){.workspace{display:flex}'));assert.match(css,/\.chat-panel\{position:fixed;right:0;top:62px;bottom:0;width:min\(390px,100vw\)/);assert.ok(css.includes('body.chat-hidden .chat-panel{display:none}'));});

test('explicit model refresh bypasses directory cache without sending or replacing the selected model and draft',async()=>{
 const h=harness();h.ui.state.selectedModel='existing';h.get('message').value='未发送的原始问题';h.ui.persistChatDraft();
 h.get('refresh-models').fire('click');assert.equal(h.get('refresh-models').disabled,true);assert.equal(h.requests.length,1);assert.equal(h.requests[0].url,'/api/models?refresh=1');
 h.requests[0].respond({models:[{id:'existing',label:'原模型',selectable:true},{id:'gpt-6.1-sol',label:'GPT-6.1-Sol',selectable:true}],default_id:'gpt-6.1-sol'});await settle();
 assert.equal(h.ui.state.selectedModel,'existing');assert.equal(h.get('model-select').value,'existing');assert.equal(h.get('message').value,'未发送的原始问题');assert.equal(h.ui.drafts().chat(''),'未发送的原始问题');assert.equal(h.requests.length,1);assert.equal(h.get('refresh-models').disabled,false);
 const loading=h.ui.loadModels();assert.equal(h.requests[1].url,'/api/models');h.requests[1].respond({models:[{id:'existing',selectable:true}]});await loading;
});
